class Solution {
    public int[] moveZeroes(int[] nums) {
        int slow = 0;

        for (int fast = 0; fast < nums.length; fast++) {
            if (nums[fast] != 0) {
                int temp = nums[slow];
                nums[slow] = nums[fast];
                nums[fast] = temp;
                slow++;
            }
        }

        return nums;
    }
}

class Solution {
    public int[] moveZeroes(int[] nums) {
        int insertPos = 0;

        // Move all non-zero elements to front
        for (int num : nums) {
            if (num != 0) {
                nums[insertPos++] = num;
            }
        }

        // Fill rest with zeros
        while (insertPos < nums.length) {
            nums[insertPos++] = 0;
        }

        return nums;
    }
}

class Solution {
    public int[] moveZeroes(int[] nums) {
        int snowBall = 0;

        for (int i = 0; i < nums.length; i++) {
            if (nums[i] == 0) {
                snowBall++;
            } else if (snowBall > 0) {
                nums[i - snowBall] = nums[i];
                nums[i] = 0;
            }
        }

        return nums;
    }
}
